SELECT f.id, f.symbol, f.signal_id, f.evaluated_at, f.stage, LEFT(f.payload, 900) AS payload FROM fix122_evaluation f WHERE f.test_run_id IS NULL AND ((f.symbol = 'EGLDUSDT' AND f.evaluated_at BETWEEN '2026-10-11 22:35:00' AND '2026-10-11 22:40:05') OR (f.symbol = 'DOGEUSDT' AND f.evaluated_at BETWEEN '2026-10-12 04:01:30' AND '2026-10-12 04:02:06')) ORDER BY f.evaluated_at LIMIT 40